latihan-algoritma-fibonacci-bubble-sort-.code:
void main() {
  // Fibonacci: for, jumlah suku diketahui
  var a = 0, b = 1;
  var deret = '';
  for (var i = 0; i < 10; i++) {
    deret += '$a ';
    final berikut = a + b;   // variabel bantu
    a = b;
    b = berikut;
  }
  print('Fibonacci: $deret');

  // Bubble sort: while luar, for dalam
  final data = [64, 25, 12, 22, 11];
  var adaTukar = true;
  while (adaTukar) {
    adaTukar = false;
    for (var j = 0; j < data.length - 1; j++) {
      if (data[j] > data[j + 1]) {
        final t = data[j];
        data[j] = data[j + 1];
        data[j + 1] = t;
        adaTukar = true;
      }
    }
  }
  print('Terurut: $data');

  // Prima: for bersarang + break
  var prima = '';
  for (var x = 2; x <= 30; x++) {
    var isPrima = true;
    for (var d = 2; d * d <= x; d++) {
      if (x % d == 0) {
        isPrima = false;
        break;
      }
    }
    if (isPrima) prima += '$x ';
  }
  print('Prima: $prima');
}

