enum Metode { tunai, qris }

class UangKurang implements Exception {
  final int kurang;
  UangKurang(this.kurang);
  @override
  String toString() => 'Uang kurang Rp${rp(kurang)}';
}

int bayar(int tagihan, Metode metode, {int uang = 0}) {
  if (metode == Metode.qris) return 0;
  if (uang < tagihan) throw UangKurang(tagihan - uang);
  return uang - tagihan;
}

void main() {
  const tagihan = 66150;
  for (final uang in [100000, 50000]) {
    try {
      final kembali = bayar(tagihan, Metode.tunai, uang: uang);
      print('Tunai ${rp(uang)}, kembali ${rp(kembali)}');
    } on UangKurang catch (e) {
      print(e);
    }
  }
  print('QRIS, kembali ${rp(bayar(tagihan, Metode.qris))}');
}
